create extension if not exists pgcrypto;
create extension if not exists btree_gist;
create type public.app_role as enum ('super_admin','owner','staff');
create type public.appointment_status as enum ('Pending','Confirmed','Arrived','Completed','Cancelled','No-show');
create type public.payment_method as enum ('Cash','UPI','Card','Other');
create table public.users (id uuid primary key references auth.users(id) on delete cascade, name text not null, mobile text, email text unique not null, role app_role not null default 'owner', created_at timestamptz default now(), updated_at timestamptz default now());
create table public.subscription_plans (id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, monthly_price_inr int not null, limits jsonb not null, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.salons (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, location text not null, address text, google_maps_url text, phone text, whatsapp text, logo_url text, cover_url text, description text, active boolean default true, owner_id uuid references public.users(id), subscription_plan_id uuid references public.subscription_plans(id), subscription_status text default 'active', created_at timestamptz default now(), updated_at timestamptz default now());
create table public.salon_users (id uuid primary key default gen_random_uuid(), salon_id uuid references public.salons(id) on delete cascade, user_id uuid references public.users(id) on delete cascade, role app_role not null, active boolean default true, created_at timestamptz default now(), unique(salon_id,user_id));
create table public.staff (id uuid primary key default gen_random_uuid(), salon_id uuid references public.salons(id) on delete cascade, user_id uuid references public.users(id), name text not null, phone text, role text, specialization text, working_days text[] default '{}', work_start time, work_end time, active boolean default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.services (id uuid primary key default gen_random_uuid(), salon_id uuid references public.salons(id) on delete cascade, name text not null, category text not null, price_inr int not null, duration_minutes int not null, description text, active boolean default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.staff_services (staff_id uuid references public.staff(id) on delete cascade, service_id uuid references public.services(id) on delete cascade, primary key(staff_id, service_id));
create table public.customers (id uuid primary key default gen_random_uuid(), salon_id uuid references public.salons(id) on delete cascade, name text not null, mobile text not null, whatsapp text, gender text, birthday date, notes text, last_visit timestamptz, total_visits int default 0, total_spending_inr int default 0, favorite_services text[] default '{}', created_at timestamptz default now(), updated_at timestamptz default now(), unique(salon_id,mobile));
create table public.membership_plans (id uuid primary key default gen_random_uuid(), salon_id uuid references public.salons(id) on delete cascade, name text not null, price_inr int not null, benefits text[] default '{}', active boolean default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.memberships (id uuid primary key default gen_random_uuid(), salon_id uuid references public.salons(id) on delete cascade, customer_id uuid references public.customers(id) on delete cascade, membership_plan_id uuid references public.membership_plans(id), start_date date, expiry_date date, status text check(status in ('Active','Expired')) default 'Active', created_at timestamptz default now(), updated_at timestamptz default now());
create table public.appointments (id uuid primary key default gen_random_uuid(), salon_id uuid references public.salons(id) on delete cascade, customer_id uuid references public.customers(id), staff_id uuid references public.staff(id), appointment_date date not null, start_time time not null, end_time time not null, status appointment_status default 'Pending', notes text, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.appointment_services (appointment_id uuid references public.appointments(id) on delete cascade, service_id uuid references public.services(id), price_inr int not null, duration_minutes int not null, primary key(appointment_id, service_id));
create table public.sales (id uuid primary key default gen_random_uuid(), salon_id uuid references public.salons(id) on delete cascade, appointment_id uuid references public.appointments(id), customer_id uuid references public.customers(id), service_amount_inr int not null, discount_inr int default 0, final_amount_inr int not null, payment_method payment_method not null, created_at timestamptz default now());
create table public.payments (id uuid primary key default gen_random_uuid(), salon_id uuid references public.salons(id) on delete cascade, sale_id uuid references public.sales(id), amount_inr int not null, method payment_method not null, created_at timestamptz default now());
create table public.offers (id uuid primary key default gen_random_uuid(), salon_id uuid references public.salons(id) on delete cascade, name text not null, description text, discount_type text check(discount_type in ('Percentage','Fixed amount')), discount_amount int not null, start_date date, end_date date, applicable_services uuid[] default '{}', active boolean default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.message_templates (id uuid primary key default gen_random_uuid(), salon_id uuid references public.salons(id) on delete cascade, template_key text not null, body text not null, created_at timestamptz default now(), updated_at timestamptz default now(), unique(salon_id,template_key));
create table public.messages (id uuid primary key default gen_random_uuid(), salon_id uuid references public.salons(id) on delete cascade, customer_id uuid references public.customers(id), channel text default 'whatsapp_click_to_chat', body text not null, click_url text, sent_by uuid references public.users(id), created_at timestamptz default now());
create table public.subscriptions (id uuid primary key default gen_random_uuid(), salon_id uuid references public.salons(id) on delete cascade, plan_id uuid references public.subscription_plans(id), status text default 'active', current_period_start date, current_period_end date, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.salon_settings (salon_id uuid primary key references public.salons(id) on delete cascade, timezone text default 'Asia/Kolkata', currency text default 'INR', locale text default 'en-IN', created_at timestamptz default now(), updated_at timestamptz default now());
create table public.working_hours (id uuid primary key default gen_random_uuid(), salon_id uuid references public.salons(id) on delete cascade, day_of_week int check(day_of_week between 0 and 6), opens_at time, closes_at time, closed boolean default false, created_at timestamptz default now());
create unique index appointments_no_double_booking on public.appointments(staff_id, appointment_date, start_time) where status in ('Pending','Confirmed','Arrived');
create index on public.salons(active); create index on public.salon_users(user_id); create index on public.staff(salon_id); create index on public.services(salon_id); create index on public.customers(salon_id); create index on public.customers(mobile); create index on public.appointments(salon_id, appointment_date); create index on public.appointments(customer_id); create index on public.appointments(staff_id); create index on public.appointments(status); create index on public.sales(salon_id, created_at);
create or replace function public.is_super_admin() returns boolean language sql stable security definer as $$ select exists(select 1 from public.users where id=auth.uid() and role='super_admin') $$;
create or replace function public.has_salon_access(target uuid) returns boolean language sql stable security definer as $$ select public.is_super_admin() or exists(select 1 from public.salon_users where salon_id=target and user_id=auth.uid() and active) $$;
alter table public.users enable row level security; alter table public.salons enable row level security; alter table public.salon_users enable row level security; alter table public.staff enable row level security; alter table public.services enable row level security; alter table public.staff_services enable row level security; alter table public.customers enable row level security; alter table public.appointments enable row level security; alter table public.appointment_services enable row level security; alter table public.sales enable row level security; alter table public.payments enable row level security; alter table public.offers enable row level security; alter table public.memberships enable row level security; alter table public.membership_plans enable row level security; alter table public.message_templates enable row level security; alter table public.messages enable row level security; alter table public.subscriptions enable row level security; alter table public.subscription_plans enable row level security; alter table public.salon_settings enable row level security; alter table public.working_hours enable row level security;
create policy users_self_or_admin on public.users for all using (id=auth.uid() or public.is_super_admin()) with check (id=auth.uid() or public.is_super_admin());
create policy public_active_salons on public.salons for select using (active or public.has_salon_access(id)); create policy salon_manage on public.salons for all using (public.has_salon_access(id)) with check (public.has_salon_access(id));
create policy plans_read on public.subscription_plans for select using (true); create policy plans_admin on public.subscription_plans for all using (public.is_super_admin()) with check (public.is_super_admin());
create policy salon_users_access on public.salon_users for all using (public.has_salon_access(salon_id)) with check (public.has_salon_access(salon_id));
create policy staff_access on public.staff for all using (public.has_salon_access(salon_id)) with check (public.has_salon_access(salon_id));
create policy services_public_read on public.services for select using (active); create policy services_manage on public.services for all using (public.has_salon_access(salon_id)) with check (public.has_salon_access(salon_id));
create policy staff_services_access on public.staff_services for all using (exists(select 1 from public.staff st where st.id=staff_id and public.has_salon_access(st.salon_id))) with check (exists(select 1 from public.staff st where st.id=staff_id and public.has_salon_access(st.salon_id)));
create policy customers_access on public.customers for all using (public.has_salon_access(salon_id)) with check (public.has_salon_access(salon_id));
create policy appointments_access on public.appointments for all using (public.has_salon_access(salon_id)) with check (public.has_salon_access(salon_id));
create policy appointment_services_access on public.appointment_services for all using (exists(select 1 from public.appointments ap where ap.id=appointment_id and public.has_salon_access(ap.salon_id))) with check (exists(select 1 from public.appointments ap where ap.id=appointment_id and public.has_salon_access(ap.salon_id)));
create policy salon_scoped_access on public.sales for all using (public.has_salon_access(salon_id)) with check (public.has_salon_access(salon_id));
create policy payments_access on public.payments for all using (public.has_salon_access(salon_id)) with check (public.has_salon_access(salon_id));
create policy offers_public_read on public.offers for select using (active); create policy offers_manage on public.offers for all using (public.has_salon_access(salon_id)) with check (public.has_salon_access(salon_id));
create policy memberships_access on public.memberships for all using (public.has_salon_access(salon_id)) with check (public.has_salon_access(salon_id)); create policy membership_plans_access on public.membership_plans for all using (public.has_salon_access(salon_id)) with check (public.has_salon_access(salon_id));
create policy template_access on public.message_templates for all using (public.has_salon_access(salon_id)) with check (public.has_salon_access(salon_id)); create policy messages_access on public.messages for all using (public.has_salon_access(salon_id)) with check (public.has_salon_access(salon_id));
create policy subs_access on public.subscriptions for all using (public.has_salon_access(salon_id)) with check (public.has_salon_access(salon_id)); create policy settings_access on public.salon_settings for all using (public.has_salon_access(salon_id)) with check (public.has_salon_access(salon_id)); create policy hours_access on public.working_hours for all using (public.has_salon_access(salon_id)) with check (public.has_salon_access(salon_id));
insert into public.subscription_plans(code,name,monthly_price_inr,limits) values ('FREE','Free',0,'{"appointments_per_month":50,"staff":1}'),('BASIC','Basic',499,'{"appointments_per_month":"unlimited","staff":5}'),('PRO','Pro',999,'{"appointments_per_month":"unlimited","staff":"unlimited"}') on conflict do nothing;
